const N = 2048;
const m = new Int32Array(N * N).fill(1);   // matriz de N x N guardada fila tras fila

function porFilas() {                       // recorre en el orden en que está guardada
  let s = 0;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) s += m[i * N + j];
  return s;
}
function porColumnas() {                    // salta N casillas en cada paso
  let s = 0;
  for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) s += m[i * N + j];
  return s;
}
function medir(nombre, f) {
  f();                                      // una pasada de calentamiento
  const t0 = performance.now();
  const r = f();
  console.log(nombre, r, (performance.now() - t0).toFixed(1) + " ms");
}
medir("por filas   ", porFilas);
medir("por columnas", porColumnas);
